; Generated by nt65 from main.nt65. Do not edit.
.setcpu "W65C02"
.smart -
.case +
.feature at_in_identifiers -, bracket_as_indirect -, c_comments -
.feature dollar_in_identifiers -, dollar_is_pc -, force_range -, labels_without_colons -
.feature leading_dot_in_identifiers -, line_continuations -, long_jsr_jmp_rts -
.feature loose_char_term -, loose_string_term -, missing_char_term -, org_per_seg -
.feature pc_assignment -, string_escapes -, ubiquitous_idents -, underline_in_numbers -

.export main__bits
.export main__dispatch
.export main__commands
.export main__actions_table
.export main__grid

LINES = 312

TRACE = 1

.segment "CODE": absolute
main:

main__again:
    jsr trace
    bne main__again
    ldy #$03
    lda #<LINES
    ldx #>LINES
    rts

trace:
    phx
    plx
    rts

    .assert main >= $0200, lderror, "main must be past the zero page"
    .assert (main <> trace) && (main = main), lderror, "ca65 spells these operators its own way"

Cmd__move = $00
Cmd__fire = $01
Cmd__wait = $02

.segment "RODATA": absolute
main__bits:
        .byte 1 << $00              ; i
        .byte 1 << $01              ; i
        .byte 1 << $02              ; i
        .byte 1 << $03              ; i
        .byte 1 << $04              ; i
        .byte 1 << $05              ; i
        .byte 1 << $06              ; i
        .byte 1 << $07              ; i

main__dispatch:
        .addr main - 1              ; h
        .addr trace - 1             ; h

main__commands:
        .byte $00                   ; c
        .byte $01                   ; c
        .byte $02                   ; c

main__actions_table:
        .addr actions__move
        .addr actions__fire
        .addr actions__wait

main__grid:
            .byte ($00 * 3) + $00   ; row, col
            .byte ($00 * 3) + $01   ; row, col
            .byte ($00 * 3) + $02   ; row, col
            .byte ($01 * 3) + $00   ; row, col
            .byte ($01 * 3) + $01   ; row, col
            .byte ($01 * 3) + $02   ; row, col

    COLUMNS = 80

.segment "CODE": absolute
indented:
        lda #COLUMNS
    rts

actions__move:
    rts
actions__fire:
    jmp actions__move
actions__wait:
    rts

slow:
    ldx #$00 + 1                    ; i
slow__delay:
    dex
    bne slow__delay
    bcc slow__skip
    nop
slow__skip:
    ldx #$01 + 1                    ; i
slow__delay_2:
    dex
    bne slow__delay_2
    bcc slow__skip_2
    nop
slow__skip_2:
    ldx #$02 + 1                    ; i
slow__delay_3:
    dex
    bne slow__delay_3
    bcc slow__skip_3
    nop
slow__skip_3:
    rts

run_all:
    jsr actions__move
    jsr actions__fire
    jsr actions__wait
    rts
